import { createEnv } from '@t3-oss/env-nextjs';
import { vercel } from '@t3-oss/env-nextjs/presets-zod';

import { secretSchema } from '@/schemas/common';

export const env = createEnv({
  emptyStringAsUndefined: true,
  experimental__runtimeEnv: process.env,
  extends: [vercel()],

  onInvalidAccess: (variable: string) => {
    console.error(
      '❌ Attempted to access a server-side environment variable on the client: ',
      variable
    );

    throw new Error('❌ Attempted to access a server-side environment variable on the client');
  },

  onValidationError: (issues) => {
    console.error('❌ Invalid environment variables:', issues);

    throw new Error('❌ Invalid environment variables');
  },

  server: {
    // clerk api keys
    CLERK_SECRET_KEY: secretSchema.startsWith('sk_'),

    // openai api key
    OPENAI_API_KEY: secretSchema.startsWith('sk-'),

    // convex internal key (generated by `openssl rand -hex 32`)
    POLARIS_CONVEX_INTERNAL_KEY: secretSchema,

    // firecrawl api key
    FIRECRAWL_API_KEY: secretSchema.startsWith('fc-'),
  },
});
